function updateToolbar(){if(!rich)return;const map={bold:'bold',italic:'italic',underline:'underline',insertUnorderedList:'bulletList',insertOrderedList:'orderedList'};for(const b of $$('[data-command]')){const active=!!map[b.dataset.command]&&rich.isActive(map[b.dataset.command]);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}const para=$('[data-action=paragraph]');if(para)para.textContent=rich.isActive('heading',{level:2})?'大標題 ▾':rich.isActive('heading',{level:3})?'小標題 ▾':'正文 ▾'}
function closePopover(){$('#popover').hidden=true;if(popTrigger)popTrigger.setAttribute('aria-expanded','false');popTrigger=null}
function popover(trigger,html){const p=$('#popover');if(!p.hidden&&popTrigger===trigger){closePopover();return}closePopover();p.innerHTML=html;p.hidden=false;popTrigger=trigger;trigger?.setAttribute('aria-expanded','true');const r=trigger.getBoundingClientRect();const width=p.offsetWidth,height=p.offsetHeight;p.style.left=Math.max(12,Math.min(innerWidth-width-12,r.left))+'px';p.style.top=(r.top>innerHeight/2?Math.max(10,r.top-height-10):Math.min(innerHeight-height-10,r.bottom+8))+'px';decorate()}
function dialog(title,html){closePopover();$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal();decorate()}
function closeDialog(){if(recorder?.state==='recording'||recorder?.state==='paused'){recorder.stop()}$('#dialog').close()}
function closeSidebar(){$('#sidebar').classList.remove('is-open');$('#veil').hidden=true}
function applySettings(){document.body.classList.toggle('dark',settings.theme==='dark');document.documentElement.style.setProperty('--editor-size',settings.size+'px');document.documentElement.style.setProperty('--editor-leading',settings.leading);document.documentElement.style.setProperty('--measure',settings.wide?'920px':'740px')}
function download(name,content,mime){const blob=content instanceof Blob?content:new Blob([content],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function safeFilename(s){return s.replace(/[\\/:*?"<>|\u0000-\u001f]/g,'-').slice(0,80)||'筆記'}
async function backup(){await flush();const data={format:'liubai-notes',version:1,exportedAt:new Date().toISOString(),folders,settings,notes:notes.filter(n=>meaningful(n)||n.deleted)};download('liubai-backup-'+today()+'.json',JSON.stringify(data,null,2),'application/json');toast('備份已匯出，包含圖片、附件與版本歷史')}
function markdown(html){const doc=new DOMParser().parseFromString(cleanHTML(html),'text/html');function walk(n){if(n.nodeType===3)return n.textContent;if(n.nodeType!==1)return '';const inner=[...n.childNodes].map(walk).join('');switch(n.tagName){case 'H1':case 'H2':case 'H3':case 'H4':return '\n\n'+'#'.repeat(Number(n.tagName[1]))+' '+inner+'\n\n';case 'P':case 'DIV':return inner+'\n\n';case 'BR':return '\n';case 'STRONG':case 'B':return '**'+inner+'**';case 'I':case 'EM':return '*'+inner+'*';case 'PRE':return '\n```\n'+n.textContent+'\n```\n';case 'CODE':return '`'+inner+'`';case 'LI':return '- '+inner+'\n';case 'BLOCKQUOTE':return '\n> '+inner.trim().replace(/\n/g,'\n> ')+'\n';case 'A':return '['+inner+']('+n.getAttribute('href')+')';case 'IMG':return '\n!['+(n.getAttribute('alt')||'圖片')+']('+n.getAttribute('src')+')\n';case 'INPUT':return n.checked?'[x] ':'[ ] ';case 'HR':return '\n---\n';default:return inner}}return [...doc.body.childNodes].map(walk).join('').replace(/\n{3,}/g,'\n\n').trim()}
function exportNote(){const n=getCurrent();if(!n)return;download(safeFilename(titleOf(n))+'.md','# '+titleOf(n)+'\n\n'+markdown(editor.innerHTML),'text/markdown;charset=utf-8');toast('已匯出 Markdown；完整備份可保留所有格式')}
function confirmDelete(){const n=getCurrent();if(!n)return;dialog('移到回收站？',`<p>「${esc(titleOf(n))}」會保留在回收站，你可以稍後還原。</p><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="danger-button" data-action="delete-confirm">移到回收站</button></div>`)}
async function removeCurrent(){if(!(await flush()))return;const n=getCurrent();if(!n)return;const previous=n.deleted;n.deleted=true;n.deletedAt=Date.now();try{await storeNote(n)}catch{n.deleted=previous;toast('未能儲存，已取消刪除');return}selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open','focus-mode');closeDialog();renderList();toast('已移到回收站');dialog('已移到回收站','<p>你可以立即撤銷，或稍後從回收站還原。</p><button class="primary" data-action="restore-trash" data-id="'+esc(n.id)+'">撤銷刪除</button>')}
function showTrash(n){dialog('回收站',`<h3>${esc(titleOf(n))}</h3><p>刪除於 ${new Date(n.deletedAt||n.updated).toLocaleString('zh-HK')}</p><p>${esc(textOf(n.html).slice(0,200))}</p><div class="dialog-footer"><button class="secondary" data-action="restore-trash" data-id="${esc(n.id)}">還原筆記</button><button class="danger-button" data-action="permanent-confirm" data-id="${esc(n.id)}">永久刪除…</button></div>`)}
function showHistory(){const n=getCurrent();if(!n)return;dialog('版本歷史',`<p>保留最近 20 個文字版本。還原前會先保留目前內容。</p><button class="secondary" data-action="snapshot">＋ 儲存目前版本</button>${(n.history||[]).map((h,i)=>`<div class="version-row"><div>${esc(h.title||textOf(h.html).slice(0,30)||'無標題')}<small>${new Date(h.at).toLocaleString('zh-HK')} · ${countWords(h)} 字</small></div><button class="secondary" data-action="preview-version" data-index="${i}">查看</button></div>`).join('')||'<p>開始編輯後，這裡會留下歷史版本。</p>'}`)}
function showSettings(){dialog('閱讀與顯示',`<div class="setting-row"><span>主題</span><select id="setting-theme"><option value="light">淺色</option><option value="dark">深色</option></select></div><div class="setting-row"><span>正文字級 <b id="size-value">${settings.size}</b> px</span><input id="setting-size" type="range" min="14" max="24" value="${settings.size}" aria-label="正文字級"></div><div class="setting-row"><span>行距</span><select id="setting-leading"><option value="1.65">緊湊</option><option value="1.95">舒適</option><option value="2.2">寬鬆</option></select></div><div class="setting-row"><span>寬版正文</span><input id="setting-wide" type="checkbox" ${settings.wide?'checked':''} aria-label="寬版正文"></div><p>內容儲存在目前瀏覽器。離線時會保留在本機；從日曆開啟時，依目前日曆帳號同步。</p><button class="secondary" data-action="backup">匯出完整備份</button>`);$('#setting-theme').value=settings.theme;$('#setting-leading').value=String(settings.leading)}
function manageFolders(){dialog('管理資料夾',`<p>移除資料夾後，裡面的筆記會移至「未分類」。</p>${folders.map((f,i)=>`<div class="folder-manage-row"><span>${esc(f)}</span><div><button class="icon" data-action="folder-up" data-index="${i}" ${i===0?'disabled':''} aria-label="${esc(f)}向上移">↑</button><button class="icon" data-action="folder-down" data-index="${i}" ${i===folders.length-1?'disabled':''} aria-label="${esc(f)}向下移">↓</button><button class="icon" data-action="folder-delete" data-index="${i}" aria-label="移除${esc(f)}">×</button></div></div>`).join('')}<div class="dialog-footer"><button class="secondary" data-action="new-folder">＋ 新增資料夾</button></div>`)}
function showOutline(){const headings=$$('h1,h2,h3,h4',editor);dialog('文章目錄',headings.length?headings.map((h,i)=>`<button class="outline-entry" style="padding-left:${(Number(h.tagName[1])-1)*14+8}px" data-action="jump-heading" data-index="${i}">${esc(h.textContent)}</button>`).join(''):'<p>把段落設為標題後，會在這裡自動整理成目錄。</p>')}
async function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file.type?file:new Blob([file],{type:'application/octet-stream'}))})}
async function insertFiles(files,images){if(!getCurrent()||!files.length)return;const noteId=selected,range=savedRange?.cloneRange();let html='';try{for(const f of files){if(f.size>10*1024*1024){toast('單一檔案上限為 10 MB');continue}if(images&&!/^image\/(png|jpeg|gif|webp)$/i.test(f.type)){toast('請選擇 PNG、JPEG、WebP 或 GIF 圖片');continue}const data=await readFile(f);html+=images?`<p><img src="${esc(data)}" alt="${esc(f.name)}"></p><p><br></p>`:`<a class="attachment" href="${esc(data)}" download="${esc(f.name)}" contenteditable="false">📎 ${esc(f.name)} · ${(f.size/1024).toFixed(0)} KB</a><p><br></p>`}if(noteId!==selected){toast('已切換筆記，請在需要的位置重新插入');return}savedRange=range;if(html){insertHTML(html);await flush();toast(images?'圖片已插入正文':'檔案已加入')}}catch{toast('讀取檔案失敗，請重新選擇')}}
function normalizeImport(data){if(!data||data.format!=='liubai-notes'||data.version!==1||!Array.isArray(data.notes))throw Error('請選擇留白匯出的完整 JSON 備份');if(data.notes.length>10000)throw Error('一次最多匯入 10,000 則記錄');const ids=new Set();return data.notes.map(n=>{if(!n||typeof n.id!=='string'||!['note','diary'].includes(n.kind)||typeof n.html!=='string'||ids.has(n.id))throw Error('備份中的筆記資料不完整或有重複 ID');ids.add(n.id);return {...n,id:n.id.slice(0,160),kind:n.kind,title:String(n.title||'').slice(0,300),html:cleanHTML(n.html),folder:String(n.folder||'').slice(0,60),tags:Array.isArray(n.tags)?n.tags.map(x=>String(x).slice(0,60)).slice(0,30):[],mood:String(n.mood||''),date:/^\d{4}-\d\d-\d\d$/.test(n.date)?n.date:today(),created:Number(n.created)||Date.now(),updated:Number(n.updated)||Date.now(),pinned:!!n.pinned,deleted:!!n.deleted,deletedAt:Number(n.deletedAt)||0,history:Array.isArray(n.history)?n.history.slice(0,20).map(h=>({at:Number(h.at)||Date.now(),title:String(h.title||'').slice(0,300),html:cleanHTML(h.html||'')})):[]}})}
let pendingImport=null;
async function prepareImport(file){if(!file)return;try{if(file.size>150*1024*1024)throw Error('備份檔案上限為 150 MB');const data=JSON.parse(await file.text());const incoming=normalizeImport(data);pendingImport={incoming,folders:Array.isArray(data.folders)?data.folders.filter(x=>typeof x==='string').map(x=>x.slice(0,60)):[]};dialog('匯入備份',`<p>找到 ${incoming.length} 則記錄。匯入會合併內容；同一篇以較新的版本為準，不會清空現有筆記。</p><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="primary" data-action="import-confirm">合併匯入</button></div>`)}catch(e){toast(e.message||'無法讀取這個備份')}}
async function doImport(){if(!pendingImport||!(await flush()))return;const batch=pendingImport;let saved=0;try{for(const n of batch.incoming){const old=notes.find(x=>x.id===n.id);if(old&&old.updated>=n.updated)continue;await storeNote(n);if(old)notes[notes.indexOf(old)]=n;else notes.push(n);saved++}folders=[...new Set([...folders,...batch.folders,...batch.incoming.map(n=>n.folder).filter(Boolean)])];await storeConfig();pendingImport=null;closeDialog();selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open','focus-mode');renderList();toast(`已合併 ${saved} 則記錄`)}catch{toast(`已完成 ${saved} 則，其餘未能儲存。原有筆記仍保留。`);renderList()}}
async function action(name,button){
  switch(name){
  case 'new':await createNote();break;
  case 'back':await back();break;
  case 'kind':await navigate(button.dataset.kind,'all');break;
  case 'sidebar':$('#sidebar').classList.add('is-open');$('#veil').hidden=false;break;
  case 'scope':scopeAll=!scopeAll;renderList();break;
  case 'clear-search':query='';$('#search').value='';renderList();break;
  case 'sort':sort=sort==='updated'?'created':sort==='created'?'manual':'updated';$('#sort-button').title=sort==='updated'?'依最後編輯排序':'依建立日期排序';renderList();break;
  case 'meta':metaOpen=!metaOpen;updateHeader();break;
  case 'focus':document.body.classList.toggle('focus-mode');break;
  case 'pin':{const n=getCurrent();if(n){n.pinned=!n.pinned;pending=true;await flush();updateHeader();renderList()}break}
  case 'more':popover(button,`<div class="menu-label">這篇筆記</div><button data-action="pin">☆　${getCurrent()?.pinned?'取消置頂':'置頂筆記'}</button><button data-action="meta">☷　分類與詳細資料</button><button data-action="chapter-view">章節</button><button data-action="manual-up">清單向上移</button><button data-action="manual-down">清單向下移</button><button data-action="previous-note">上一篇</button><button data-action="next-note">下一篇</button><button data-action="reader">閱讀模式</button><button data-action="archive">歸檔／取消歸檔</button><button data-action="full-meta">筆記本、章節及日記資料</button><button data-action="exports">分享與匯出</button><button data-action="template-save">存成模板</button><button data-action="links">關聯筆記</button><button data-action="find-open">搜尋正文</button><button data-action="history">↶　版本歷史</button><button data-action="export-note">↗　匯出 Markdown</button><button class="danger" data-action="delete">♲　移到回收站</button>`);break;
  case 'insert':popover(button,'<button data-action="templates">套用模板</button><button data-action="record">錄音</button><button data-action="media-file">音訊／影片</button><button data-action="insert-time">插入時間</button><button data-action="table">表格工具</button><button data-action="choose-image">▧　插入圖片</button><button data-action="choose-file">♧　加入檔案</button><button data-action="checkbox">☑　核對清單</button><button data-action="link">↗　插入連結</button><button data-action="divider">―　分隔線</button>');break;
  case 'format':popover(button,'<div class="menu-label">文字與段落</div><button data-action="colors">文字／螢光顏色</button><button data-action="indent">增加縮排</button><button data-action="outdent">減少縮排</button><button data-action="toolbar">自訂工具列</button><button data-command="underline"><u>U</u>　底線</button><button data-command="strikeThrough"><s>S</s>　刪除線</button><button data-block="h2">H₂　標題</button><button data-block="h3">H₃　小標題</button><button data-command="insertOrderedList">1.　編號清單</button><button data-block="blockquote">❝　引用</button><button data-action="code">&lt;/&gt;　程式碼區塊</button><button data-command="removeFormat">Tx　清除文字格式</button>');break;
  case 'choose-image':closePopover();$('#image-input').click();break;
  case 'choose-file':closePopover();$('#attachment-input').click();break;
  case 'checkbox':rich.chain().focus().toggleTaskList().run();break;
  case 'divider':insertHTML('<hr><p><br></p>');break;
  case 'code':block('pre');break;
  case 'link':dialog('插入連結','<label>網址<input class="dialog-body-input" id="link-url" placeholder="https://"></label><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="primary" data-action="insert-link">插入</button></div>');$('#link-url').focus();break;
  case 'insert-link':{const url=$('#link-url').value.trim();if(!/^https?:\/\//i.test(url)){toast('請輸入以 https:// 或 http:// 開頭的網址');return}closeDialog();restoreSelection();if(getSelection().isCollapsed)insertHTML(`<a href="${esc(url)}">${esc(url)}</a>`);else command('createLink',url);break}
  case 'backup':await backup();break;
  case 'export-note':exportNote();closePopover();break;
  case 'import':closePopover();$('#backup-input').click();break;
  case 'import-confirm':await doImport();break;
  case 'settings':showSettings();break;
  case 'outline':showOutline();break;
  case 'jump-heading':{const h=$$('h1,h2,h3,h4',editor)[Number(button.dataset.index)];closeDialog();h?.scrollIntoView({behavior:'smooth',block:'start'});break}
  case 'delete':confirmDelete();break;
  case 'delete-confirm':await removeCurrent();break;
  case 'close-dialog':closeDialog();break;
  case 'history':await flush();showHistory();break;
  case 'snapshot':{const n=collectEditor();if(n){revise(n);await storeNote(n);showHistory();toast('已保留目前版本')}break}
  case 'preview-version':{const n=getCurrent(),i=Number(button.dataset.index),v=n?.history[i];if(v)dialog('查看歷史版本',`<small>${new Date(v.at).toLocaleString('zh-HK')}</small><h3>${esc(v.title||'無標題')}</h3><div style="white-space:pre-wrap;max-height:40dvh;overflow:auto">${esc(textOf(v.html))}</div><div class="dialog-footer"><button class="secondary" data-action="history">返回版本列表</button><button class="primary" data-action="restore-version" data-index="${i}">還原這個版本</button></div>`);break}
  case 'restore-version':{const n=getCurrent(),v=n?.history[Number(button.dataset.index)];if(!v)return;const copy={...v};revise(n);n.title=copy.title;n.html=copy.html;n.updated=Date.now();await storeNote(n);closeDialog();pending=false;await openNote(n.id);toast('已還原；修改前的內容仍在版本歷史');break}
  case 'restore-trash':{const n=notes.find(n=>n.id===button.dataset.id);if(!n)return;n.deleted=false;n.updated=Date.now();try{await storeNote(n)}catch{n.deleted=true;toast('還原未能儲存');return}closeDialog();renderList();toast('筆記已還原');break}
  case 'permanent-confirm':dialog('永久刪除這篇筆記？',`<p>這個操作無法還原，圖片與附件亦會一併刪除。</p><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="danger-button" data-action="permanent-delete" data-id="${esc(button.dataset.id)}">永久刪除</button></div>`);break;
  case 'permanent-delete':{const id=button.dataset.id;const old=notes;notes=notes.filter(n=>n.id!==id);try{await deleteStored(id)}catch{notes=old;toast('未能永久刪除，內容仍保留');return}closeDialog();renderList();toast('已永久刪除');break}
  case 'new-folder':dialog('新增資料夾','<input class="dialog-body-input" id="new-folder-name" maxlength="60" placeholder="例如：學習/Java（用 / 建立子資料夾）"><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="primary" data-action="create-folder">新增</button></div>');$('#new-folder-name').focus();break;
  case 'create-folder':{const f=$('#new-folder-name').value.trim();if(!f){toast('請輸入資料夾名稱');return}if(folders.includes(f)){toast('已經有這個資料夾');return}folders.push(f);await storeConfig();closeDialog();renderNav();const n=getCurrent();if(n)fillMetadata(n);toast('資料夾已建立');break}
  case 'manage-folders':manageFolders();break;
  case 'folder-up':case 'folder-down':{const i=Number(button.dataset.index),j=i+(name==='folder-up'?-1:1);if(j>=0&&j<folders.length){[folders[i],folders[j]]=[folders[j],folders[i]];await storeConfig();renderNav();manageFolders()}break}
  case 'folder-delete':{const f=folders[Number(button.dataset.index)];dialog('移除資料夾？',`<p>「${esc(f)}」裡的筆記會保留，並移至未分類。</p><div class="dialog-footer"><button class="secondary" data-action="manage-folders">取消</button><button class="primary" data-action="folder-delete-confirm" data-folder="${esc(f)}">移除資料夾</button></div>`);break}
  case 'folder-delete-confirm':{const f=button.dataset.folder;for(const n of notes.filter(n=>n.folder===f)){n.folder='';await storeNote(n)}folders=folders.filter(x=>x!==f);await storeConfig();if(filter==='folder:'+f)filter='inbox';renderList();const n=getCurrent();if(n){fillMetadata(n);updateHeader()}manageFolders();break}
  }
}
document.addEventListener('click',async e=>{if(e.target.closest('audio,video'))return;const btn=e.target.closest('button');try{if(btn?.dataset.command){command(btn.dataset.command);return}if(btn?.dataset.block){block(btn.dataset.block);return}if(btn?.dataset.open){if(batchMode){togglePick(btn.dataset.open);return}await openNote(btn.dataset.open);return}if(btn?.dataset.filter){await navigate(kind,btn.dataset.filter);return}if(btn?.dataset.action){if(await unifiedAction(btn.dataset.action,btn))return;if(await diaryAction(btn.dataset.action,btn))return;if(await fullAction(btn.dataset.action,btn))return;if(await extraAction(btn.dataset.action,btn))return;if(!['more','insert','format'].includes(btn.dataset.action))closePopover();await action(btn.dataset.action,btn);return}if(!e.target.closest('#popover'))closePopover();if(e.target=== $('#veil'))closeSidebar();if(e.target.matches('#editor img'))manageImage(e.target);if(e.target.matches('#editor input[type=checkbox]')){if(e.target.checked)e.target.setAttribute('checked','');else e.target.removeAttribute('checked');queueSave()}}catch(err){status('操作未完成，內容仍保留',true);toast('操作未能完成，請先匯出備份後重試');console.error(err)}});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-command],[data-block],#format-bar,#popover')){rememberSelection();if(e.target.closest('button'))e.preventDefault()}});
document.addEventListener('selectionchange',rememberSelection);
$('#title').addEventListener('input',()=>{autoTitle();queueSave()});$('#title').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();editor.focus()}});
for(const el of [editor,$('#title')]){el.addEventListener('compositionstart',()=>{composing=true;clearTimeout(saveTimer)});el.addEventListener('compositionend',()=>{composing=false;queueSave()})}
$('#find-text').addEventListener('input',refreshFind);
$('#search').addEventListener('input',e=>{query=e.target.value;renderList()});
