async function init(){decorate();try{db=await openDB();notes=await readStore('notes');HOST?.confirmLoaded?.(notes);const prefs=await readStore('config','preferences');if(prefs){folders=prefs.folders||folders;settings={...settings,...prefs.settings}}else{notes=HOST?[]:seed();for(const n of notes)await storeNote(n);await storeConfig()}}catch(e){if(HOST){status('無法讀取筆記，請重試',true);toast(e.message||'筆記讀取失敗');throw e}try{fallback=true;const data=JSON.parse(localStorage.getItem(KEY)||'null');if(data){notes=data.notes||[];folders=data.folders||folders;settings={...settings,...data.settings}}else{notes=seed();fallbackSave()}toast('目前使用備用儲存；建議定期匯出備份')}catch{notes=seed();status('無法儲存 · 請匯出備份',true);toast('瀏覽器禁止本機儲存，請使用完整瀏覽器開啟')}}applySettings();kind=['all','note','diary','quick'].includes(settings.lastKind)?settings.lastKind:'all';renderList();if(activeNotes().length&&matchMedia('(min-width:721px)').matches)await openNote(resultNotes()[0]?.id);try{channel=new BroadcastChannel(KEY);channel.onmessage=e=>{if(e.data.type==='note'){const n=e.data.note,old=notes.find(x=>x.id===n.id);if(n.id===dirtyId&&pending){toast('另一個視窗更新了這篇筆記，這裡保留你正在編輯的內容');return}if(!old||old.updated<=n.updated){if(old)notes[notes.indexOf(old)]=n;else notes.push(n);if(selected===n.id&&!pending){if(n.deleted){selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open')}else{$('#title').value=n.title;rich.commands.setContent(cleanHTML(n.html),{emitUpdate:false});fillMetadata(n);updateHeader();autoTitle()}}renderList()}}else if(e.data.type==='remove'){notes=notes.filter(n=>n.id!==e.data.id);renderList()}}}catch{}}
