function updateBatch(){if(!$('#batch-bar'))return;$('#batch-bar').hidden=!batchMode;$('#batch-count').textContent=`已選 ${picked.size} 則`;document.body.classList.toggle('batch-mode',batchMode);$$('[data-open]').forEach(b=>{b.classList.toggle('picked',picked.has(b.dataset.open));if(batchMode){b.setAttribute('aria-pressed',String(picked.has(b.dataset.open)))}else b.removeAttribute('aria-pressed')})}
function togglePick(id){picked.has(id)?picked.delete(id):picked.add(id);updateBatch()}
function openFind(value){$('#find-bar').hidden=false;if(value!==undefined)$('#find-text').value=value;refreshFind();if(value===undefined)$('#find-text').focus()}
function closeFind(){$('#find-bar').hidden=true;findRanges=[];if(globalThis.CSS?.highlights){CSS.highlights.delete('note-find');CSS.highlights.delete('note-current')}}
function refreshFind(){if($('#find-bar').hidden)return;const q=$('#find-text').value.toLocaleLowerCase();findRanges=[];if(q){const walker=document.createTreeWalker(editor,NodeFilter.SHOW_TEXT);let node,all='',parts=[];while(node=walker.nextNode()){parts.push({node,start:all.length});all+=node.textContent}const lower=all.toLocaleLowerCase();let i=0;while((i=lower.indexOf(q,i))!==-1){const a=parts.find(p=>i>=p.start&&i<p.start+p.node.length),z=parts.find(p=>i+q.length>p.start&&i+q.length<=p.start+p.node.length);if(a&&z){const r=document.createRange();r.setStart(a.node,i-a.start);r.setEnd(z.node,i+q.length-z.start);findRanges.push(r)}i+=Math.max(1,q.length);if(findRanges.length>=1000)break}}findIndex=Math.min(findIndex,Math.max(0,findRanges.length-1));paintFind()}
function paintFind(){const count=findRanges.length;$('#find-count').textContent=count?`${findIndex+1} / ${count}`:$('#find-text').value?'沒有結果':'0 / 0';if(globalThis.CSS?.highlights&&globalThis.Highlight){CSS.highlights.set('note-find',new Highlight(...findRanges));CSS.highlights.set('note-current',new Highlight(...(count?[findRanges[findIndex]]:[])))}if(count){const r=findRanges[findIndex],rect=r.getBoundingClientRect(),sc=$('#document-scroll'),bounds=sc.getBoundingClientRect();sc.scrollTop+=rect.top-bounds.top-80}}
function manageImage(img){imageTarget=img;const figure=img.closest('figure');dialog('圖片',`<img class="image-preview" src="${esc(img.src)}" alt="${esc(img.alt)}"><label class="image-label">圖片說明<input class="dialog-body-input" id="image-caption" value="${esc(figure?.querySelector('figcaption')?.textContent||'')}" placeholder="輸入圖片說明（選填）"></label><label class="image-label">顯示大小<select id="image-size" class="dialog-body-input"><option value="full">填滿正文寬度</option><option value="medium">中等寬度</option><option value="small">小圖</option></select></label><div class="image-tools"><button class="secondary" data-action="image-up">上移一段</button><button class="secondary" data-action="image-down">下移一段</button><button class="secondary" data-action="image-original">查看原圖</button><button class="secondary danger" data-action="image-delete">刪除圖片…</button></div><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="primary" data-action="image-save">儲存調整</button></div>`);$('#image-size').value=figure?.dataset.size||'full'}
function imageBlock(){return imageTarget?.closest('figure')||imageTarget}
function imageReplace(html){const target=imageBlock();if(!target||!editor.contains(target))return;revise(collectEditor());const range=document.createRange();range.selectNode(target);rich.commands.setTextSelection({from:rich.view.posAtDOM(target.parentNode,Array.from(target.parentNode.childNodes).indexOf(target)),to:rich.view.posAtDOM(target.parentNode,Array.from(target.parentNode.childNodes).indexOf(target)+1)});savedRange=null;closeDialog();rich.chain().focus().insertContent(html).run();queueSave();imageTarget=null}
async function extraAction(name,b){switch(name){
 case 'paragraph':popover(b,'<button data-block="p">正文</button><button data-block="h2">大標題</button><button data-block="h3">小標題</button>');return true;
 case 'find-open':closePopover();openFind();return true;
 case 'find-close':closeFind();return true;
 case 'find-next':case 'find-prev':if(findRanges.length){findIndex=(findIndex+(name==='find-next'?1:-1)+findRanges.length)%findRanges.length;paintFind()}return true;
 case 'image-save':{const caption=$('#image-caption').value.trim(),size=$('#image-size').value,src=imageTarget.src,alt=imageTarget.alt;imageReplace(`<figure data-size="${esc(size)}"><img src="${esc(src)}" alt="${esc(alt)}">${caption?`<figcaption>${esc(caption)}</figcaption>`:''}</figure>`);return true}
 case 'image-original':{const src=imageTarget.src;dialog('原圖',`<img class="image-preview" src="${esc(src)}" alt="圖片原圖"><div class="dialog-footer"><button class="secondary" data-action="image-back">返回調整</button></div>`);return true}
 case 'image-back':manageImage(imageTarget);return true;
 case 'image-delete':dialog('刪除這張圖片？','<p>只刪除這張圖片，前後文字會保留。可用復原或版本歷史還原。</p><div class="dialog-footer"><button class="secondary" data-action="image-back">取消</button><button class="danger-button" data-action="image-delete-confirm">刪除圖片</button></div>');return true;
 case 'image-delete-confirm':imageReplace('');return true;
 case 'image-up':case 'image-down':{let target=imageBlock();if(target?.parentElement?.tagName==='P'&&target.parentElement.childNodes.length===1)target=target.parentElement;if(!target)return true;let other=name==='image-up'?target.previousElementSibling:target.nextElementSibling;while(other&&!other.textContent.trim()&&!other.querySelector('img,input,a'))other=name==='image-up'?other.previousElementSibling:other.nextElementSibling;if(!other){toast('已在這一段的邊界');return true}revise(collectEditor());const from=rich.view.posAtDOM(target.parentNode,Array.from(target.parentNode.childNodes).indexOf(target));const to=from+rich.state.doc.nodeAt(from).nodeSize;const dest=rich.view.posAtDOM(other.parentNode,Array.from(other.parentNode.childNodes).indexOf(other)+(name==='image-down'?1:0));const node=rich.state.doc.nodeAt(from);let tr=rich.state.tr.delete(from,to);tr=tr.insert(dest>from?dest-(to-from):dest,node);rich.view.dispatch(tr);queueSave();closeDialog();toast('圖片位置已調整，可從版本歷史還原');return true}
 case 'batch-toggle':if(!(await flush()))return true;batchMode=!batchMode;picked.clear();updateBatch();return true;
 case 'batch-all':{const ids=resultNotes().map(n=>n.id);if(ids.every(id=>picked.has(id)))ids.forEach(id=>picked.delete(id));else ids.forEach(id=>picked.add(id));updateBatch();return true}
 case 'batch-export':if(!picked.size){toast('請先選擇筆記');return true}download('notes-selected-'+today()+'.json',JSON.stringify({format:'liubai-notes',version:1,exportedAt:new Date().toISOString(),folders,settings,notes:notes.filter(n=>picked.has(n.id))},null,2),'application/json');toast(`已匯出 ${picked.size} 則筆記`);return true;
 case 'batch-move':if(!picked.size){toast('請先選擇筆記');return true}dialog('移動所選筆記',`<p>將 ${picked.size} 則記錄移到：</p><select id="batch-folder" class="dialog-body-input"><option value="">未分類</option>${folders.map(f=>`<option>${esc(f)}</option>`).join('')}</select><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="primary" data-action="batch-move-confirm">移動</button></div>`);return true;
 case 'batch-delete':if(!picked.size){toast('請先選擇筆記');return true}if(filter==='trash'){toast('回收站內請逐篇處理永久刪除');return true}dialog('移到回收站？',`<p>所選 ${picked.size} 則記錄會移到回收站，可隨時還原。</p><div class="dialog-footer"><button class="secondary" data-action="close-dialog">取消</button><button class="danger-button" data-action="batch-delete-confirm">移到回收站</button></div>`);return true;
 case 'batch-move-confirm':case 'batch-delete-confirm':{if(!(await flush()))return true;const dest=name==='batch-move-confirm'?$('#batch-folder').value:null;let success=0;try{for(const n of notes.filter(n=>picked.has(n.id))){const before={...n};if(dest!==null)n.folder=dest;else{n.deleted=true;n.deletedAt=Date.now()}n.updated=Date.now();try{await storeNote(n)}catch(e){Object.assign(n,before);throw e}success++}}finally{closeDialog();if(getCurrent()?.deleted||notes.find(n=>n.id===selected)?.deleted){selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open')}else if(getCurrent()){fillMetadata(getCurrent());updateHeader()}picked.clear();batchMode=false;renderList();toast(`已處理 ${success} 則記錄`)}return true}
 default:return false;
}}


