function applyFullUI(){editor.addEventListener('load',e=>{if(e.target.tagName==='IMG'&&e.target.naturalHeight>e.target.naturalWidth*3)e.target.classList.add('long-image')},true);document.body.classList.toggle('reading',false);applyToolbar();document.addEventListener('click',async e=>{if(e.target.closest('[data-calendar-return]')){e.preventDefault();if(await flush()){if(HOST)HOST.returnToCalendar();else location.href='https://myh7201.github.io/my-calendar/'}}if(e.target.id==='word-count')wordStats()});$('#backup-input').onchange=async e=>{const f=e.target.files[0];if(f)await readBackup(f);e.target.value=''};}
function renderFullNav(){const nav=$('#navigation');if(!nav)return;nav.insertAdjacentHTML('beforeend',`<div class="nav-section">筆記本與標籤 <button data-action="book-new">＋</button></div>${(settings.books||[]).map(b=>`<button class="nav-button" data-action="book-open" data-id="${esc(b.id)}">${esc(b.name)}${b.rule?' · 智能':''}</button>`).join('')}<button class="nav-button" data-action="tag-picker">標籤篩選</button><button class="nav-button" data-action="archive-view">已歸檔</button>`);applyToolbar()}
function applyToolbar(){const hidden=settings.hiddenTools||[];$$('#format-bar [data-command],#format-bar [data-action]').forEach(b=>{const key=b.dataset.command||b.dataset.action;b.hidden=hidden.includes(key)});const g=$('.format-group');if(g&&settings.toolOrder){settings.toolOrder.forEach(k=>{const b=[...g.children].find(x=>(x.dataset.command||x.dataset.action)===k);if(b)g.append(b)})}}
function canOpen(id){const n=notes.find(x=>x.id===id);if(n?.unlock&&n.unlock>today()){dialog('時間膠囊',`<p>這篇記錄預定於 ${esc(n.unlock)} 解封。這是介面封存，並非加密。</p><button class="secondary" data-action="unseal" data-id="${esc(id)}">提前解除封存</button>`);return false}return true}
function formField(label,id,value='',type='text'){return `<label class="full-field">${label}<input id="${id}" type="${type}" value="${esc(value)}"></label>`}
function wordStats(){const n=getCurrent();if(!n)return;const text=textOf(n.html),cn=(text.match(/[\u3400-\u9fff]/g)||[]).length,en=(text.replace(/[\u3400-\u9fff]/g,' ').match(/[\p{L}\p{N}]+/gu)||[]).length;dialog('文章統計',`<div class="stats-grid"><b>${cn+en}<small>字／詞</small></b><b>${editor.querySelectorAll('p').length}<small>段落</small></b><b>${editor.querySelectorAll('img').length}<small>圖片</small></b><b>${Math.max(1,Math.ceil((cn+en)/350))}<small>分鐘閱讀</small></b></div>`)}
async function zipBackup(encrypted=false){await flush();const zip=new NoteKit.JSZip();zip.file('notes.json',JSON.stringify({format:'liubai-notes',version:1,exportedAt:new Date().toISOString(),notes:notes.filter(meaningful),folders,settings}));zip.file('README.txt','完整筆記備份，包含內嵌媒體與歷史版本。');let bytes=await zip.generateAsync({type:'uint8array'});if(encrypted){const pass=$('#backup-pass').value;if(pass.length<8){toast('請使用最少 8 個字元的密碼');return}const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(pass,salt);const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);download('notes-'+today()+'.lbn',JSON.stringify({format:'notes-encrypted-v1',salt:Array.from(salt),iv:Array.from(iv),data:bytes64(new Uint8Array(cipher))}),'application/json');closeDialog()}else download('notes-'+today()+'.zip',bytes,'application/zip');toast('備份已下載')}
function bytes64(b){let str='';for(let i=0;i<b.length;i+=16384)str+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(str)}
function from64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function deriveKey(pass,salt){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
let encryptedImport=null;
async function readBackup(file){try{const bytes=new Uint8Array(await file.arrayBuffer());if(bytes[0]===80&&bytes[1]===75){const zip=await NoteKit.JSZip.loadAsync(bytes);if(!zip.file('notes.json'))throw Error('找不到 notes.json');await prepareImport(new File([await zip.file('notes.json').async('string')],'notes.json'));return}const data=JSON.parse(new TextDecoder().decode(bytes));if(data.format==='notes-encrypted-v1'){encryptedImport=data;dialog('解密備份',formField('備份密碼','decrypt-pass','','password')+'<button class="primary" data-action="decrypt-backup">解密並預覽匯入</button>');return}await prepareImport(file)}catch(e){toast(e.message||'無法讀取備份')}}
async function exportWord(){const n=getCurrent();await flush();const {Document,Packer,Paragraph,TextRun,ImageRun,HeadingLevel}=NoteKit.docx;const body=new DOMParser().parseFromString(n.html,'text/html').body,children=[new Paragraph({text:titleOf(n),heading:HeadingLevel.TITLE})];for(const el of body.children){if(el.matches('figure,img')){const img=el.matches('img')?el:el.querySelector('img');if(img?.src.startsWith('data:image/')){try{const mime=img.src.split(';')[0].split('/')[1],bytes=from64(img.src.split(',')[1]);const bitmap=await createImageBitmap(new Blob([bytes]));const width=Math.min(550,bitmap.width),height=bitmap.height*width/bitmap.width;children.push(new Paragraph({children:[new ImageRun({data:bytes,type:mime==='jpeg'?'jpg':mime,transformation:{width,height}})]}));bitmap.close()}catch{children.push(new Paragraph('[圖片]'))}}else children.push(new Paragraph({children:[new TextRun({text:el.textContent||''})],heading:/^H[123]$/.test(el.tagName)?HeadingLevel['HEADING_'+el.tagName[1]]:undefined}))}download(safeFilename(titleOf(n))+'.docx',await Packer.toBlob(new Document({sections:[{children}]})))}}
async function longImage(){await flush();toast('正在產生長圖…');const src=$('.paper'),clone=src.cloneNode(true);clone.querySelector('#title').replaceWith(Object.assign(document.createElement('h1'),{textContent:$('#title').value||titleOf(getCurrent())}));clone.querySelector('.metadata')?.remove();clone.querySelectorAll('[contenteditable]').forEach(x=>x.removeAttribute('contenteditable'));clone.style.cssText='position:absolute;left:-12000px;top:0;width:800px;max-width:none;background:white;color:#1e293b;padding:40px';document.body.append(clone);try{const data=await NoteKit.toPng(clone,{pixelRatio:1.5,backgroundColor:'#ffffff',skipFonts:true});const blob=await(await fetch(data)).blob();download(safeFilename(titleOf(getCurrent()))+'.png',blob)}finally{clone.remove()}}
function hub(){dialog('設定與本機備份',`<div class="hub-grid">${[['toolbar','自訂工具列'],['feature-settings','功能顯示'],['zip','完整 ZIP 備份'],['encrypted','加密備份'],['import','匯入備份'],['settings','閱讀與顯示']].filter(([a])=>!(settings.hiddenFeatures||[]).includes(a)).map(([a,t])=>`<button class="secondary" data-action="${a}">${t}</button>`).join('')}</div><p>本機備份包含筆記、日記、封面與設定。天氣與地點可手動填寫，或主動使用晴訊定位查詢後確認加入。</p>`)}
function templatePanel(){dialog('筆記模板',[...builtinTemplates,...(settings.templates||[])].map((t,i)=>`<div class="version-row"><span>${esc(t.name)}</span><button class="secondary" data-action="template-apply" data-index="${i}">套用</button>${i>=builtinTemplates.length?`<button data-action="template-delete" data-index="${i-builtinTemplates.length}">刪除</button>`:''}</div>`).join(''))}
function fullMeta(){const n=getCurrent();if(!n)return;dialog(n.kind==='diary'?'日記詳細資料':'筆記資料',formField('章節','full-chapter',n.chapter)+formField('記錄時間','full-time',n.time||'','time')+`<div class="full-field">所屬筆記本${(settings.books||[]).filter(b=>!b.rule).map(b=>`<label><input type="checkbox" class="book-check" value="${esc(b.id)}" ${(n.books||[]).includes(b.id)?'checked':''}>${esc(b.name)}</label>`).join('')}</div>`+(n.kind==='diary'?formField('精力（1–5）','full-energy',n.energy||'','number'):'')+formField('時間膠囊解封日期（選填）','full-unlock',n.unlock||'','date')+'<button class="secondary" data-action="moods">自訂心情選項</button><div class="dialog-footer"><button class="primary" data-action="full-meta-save">儲存</button></div>')}
async function changeCurrent(fn){const n=collectEditor();if(!n)return;const before=structuredClone(n);revise(n);fn(n);n.updated=Date.now();try{await storeNote(n);pending=false;dirtyId=null;status('✓ 已儲存');updateHeader();renderList()}catch(e){Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,before);pending=true;dirtyId=n.id;status('儲存失敗 · 請重試',true);updateHeader();throw e}}
async function fullAction(a,b){switch(a){
case 'hub':hub();return true;
case 'colors':dialog('文字與螢光顏色','<label class="full-field">文字顏色<input type="color" id="text-color" value="#6c63ff"></label><label class="full-field">螢光底色<input type="color" id="mark-color" value="#fef08a"></label><div class="dialog-footer"><button class="secondary" data-action="clear-colors">清除顏色</button><button class="primary" data-action="apply-colors">套用</button></div>');return true;
case 'apply-colors':{const color=$('#text-color').value,highlight=$('#mark-color').value;closeDialog();rich.chain().focus().setColor(color).setHighlight({color:highlight}).run();return true}
case 'clear-colors':closeDialog();rich.chain().focus().unsetColor().unsetHighlight().run();return true;
case 'insert-time':insertHTML(esc(new Date().toLocaleString('zh-HK')));return true;
case 'indent':case 'outdent':rich.chain().focus()[a==='indent'?'sinkListItem':'liftListItem'](rich.isActive('taskItem')?'taskItem':'listItem').run();return true;
case 'table':dialog('表格工具',`<div class="hub-grid">${[['insertTable','插入 3×3 表格'],['addRowAfter','新增一行'],['addColumnAfter','新增一欄'],['deleteRow','刪除目前行'],['deleteColumn','刪除目前欄'],['mergeCells','合併儲存格'],['splitCell','分拆儲存格'],['deleteTable','刪除表格']].map(([k,t])=>`<button class="secondary" data-action="table-command" data-id="${k}">${t}</button>`).join('')}</div>`);return true;
case 'table-command':closeDialog();if(b.dataset.id==='insertTable')rich.chain().focus().insertTable({rows:3,cols:3,withHeaderRow:true}).run();else if(!rich.chain().focus()[b.dataset.id]().run())toast('請先將游標放在表格內');return true;
case 'manual-up':case 'manual-down':{const list=resultNotes();const i=list.findIndex(n=>n.id===selected),j=i+(a==='manual-up'?-1:1);if(j<0||j>=list.length){toast('已到邊界');return true}[list[i],list[j]]=[list[j],list[i]];for(let k=0;k<list.length;k++){list[k].order=k;await storeNote(list[k])}sort='manual';renderList();closePopover();return true}
case 'chapter-view':{const chapters=[...new Set(resultNotes().map(n=>n.chapter).filter(Boolean))];dialog('章節',chapters.map(c=>`<button class="secondary" data-action="chapter-open" data-id="${esc(c)}">${esc(c)}</button>`).join('')||'<p>在筆記資料中設定章節後會在這裡顯示。</p>');return true}
case 'chapter-open':query=b.dataset.id;$('#search').value=query;closeDialog();renderList();return true;
case 'reader':document.body.classList.toggle('reading');rich.setEditable(!document.body.classList.contains('reading'),false);closePopover();return true;
case 'previous-note':case 'next-note':{const all=resultNotes(),i=all.findIndex(n=>n.id===selected),n=all[i+(a==='next-note'?1:-1)];if(n)await openNote(n.id);else toast('已到清單邊界');closePopover();return true}
case 'archive':await changeCurrent(n=>n.archived=!n.archived);closePopover();toast('已更新歸檔狀態');return true;
case 'archive-view':closeDialog();await navigate(kind,'archive');return true;
case 'tag-picker':dialog('標籤篩選',`<div class="hub-grid">${[...new Set(activeNotes().flatMap(n=>n.tags||[]))].map(t=>`<button class="secondary" data-action="tag-open" data-id="${esc(t)}">${esc(t)}</button>`).join('')||'暫時沒有標籤'}</div>`);return true;
case 'tag-open':closeDialog();await navigate(kind,'tag:'+b.dataset.id);return true;
case 'templates':templatePanel();return true;
case 'template-save':dialog('儲存模板',formField('模板名稱','template-name',getCurrent()?titleOf(getCurrent()):'')+'<button class="primary" data-action="template-save-confirm">儲存</button>');return true;
case 'template-save-confirm':{const name=$('#template-name').value.trim();if(!name){toast('請輸入名稱');return true}settings.templates=[...(settings.templates||[]),{name,html:rich.getHTML()}];await storeConfig();closeDialog();toast('模板已儲存');return true}
case 'template-apply':{const t=[...builtinTemplates,...(settings.templates||[])][Number(b.dataset.index)];closeDialog();if(!getCurrent())await createNote();insertHTML(t.html.replaceAll('{{日期}}',getCurrent().date||today()));return true}
case 'template-delete':settings.templates.splice(Number(b.dataset.index),1);await storeConfig();templatePanel();return true;
case 'full-meta':fullMeta();return true;
case 'full-meta-save':await changeCurrent(n=>{n.chapter=$('#full-chapter').value;n.time=$('#full-time').value;n.books=$$('.book-check:checked').map(x=>x.value);n.unlock=$('#full-unlock').value;if(n.kind==='diary'&&$('#full-energy'))n.energy=$('#full-energy').value?Math.min(5,Math.max(1,Number($('#full-energy').value))):''});closeDialog();if(getCurrent()?.unlock>today()){selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open');renderList()}return true;
case 'moods':dialog('自訂心情',formField('每項以逗號分隔','custom-moods',(settings.moods||['😊 開心','😌 平靜','😔 低落','😴 疲倦']).join(','))+'<button class="primary" data-action="moods-save">儲存</button>');return true;
case 'moods-save':settings.moods=$('#custom-moods').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);await storeConfig();$('#mood').innerHTML='<option value="">未設定</option>'+settings.moods.map(m=>`<option>${esc(m)}</option>`).join('');closeDialog();return true;
case 'unseal':{const n=notes.find(n=>n.id===b.dataset.id);n.unlock='';await storeNote(n);closeDialog();await openNote(n.id);return true}
case 'books':dialog('筆記本管理',(settings.books||[]).map(book=>`<div class="version-row"><span>${esc(book.name)}</span><button class="secondary" data-action="book-delete" data-id="${esc(book.id)}">移除筆記本</button></div>`).join('')+'<button class="primary" data-action="book-new">新增筆記本</button>');return true;
case 'book-new':dialog('新增筆記本',formField('名稱','book-name')+formField('智能收錄關鍵字（選填，匹配標題與標籤）','book-rule')+'<button class="primary" data-action="book-save">建立</button>');return true;
case 'book-save':{const name=$('#book-name').value.trim();if(!name)return true;settings.books=[...(settings.books||[]),{id:uid(),name,rule:$('#book-rule').value.trim()}];await storeConfig();closeDialog();renderNav();return true}
case 'book-open':closeDialog();await navigate(kind,'book:'+b.dataset.id);return true;
case 'book-delete':settings.books=(settings.books||[]).filter(x=>x.id!==b.dataset.id);await storeConfig();renderNav();await fullAction('books');return true;
case 'links':{const n=getCurrent();dialog('關聯筆記',`<select id="link-note" class="dialog-body-input">${activeNotes().filter(x=>x.id!==n.id).map(x=>`<option value="${esc(x.id)}">${esc(titleOf(x))}</option>`).join('')}</select><button class="primary" data-action="link-note-add">加入連結</button><h3>已關聯</h3>${(n.links||[]).map(id=>notes.find(x=>x.id===id)).filter(Boolean).map(x=>`<button class="secondary" data-action="linked-open" data-id="${esc(x.id)}">${esc(titleOf(x))}</button>`).join('')}<h3>反向連結</h3>${activeNotes().filter(x=>(x.links||[]).includes(n.id)).map(x=>`<button class="secondary" data-action="linked-open" data-id="${esc(x.id)}">${esc(titleOf(x))}</button>`).join('')}`);return true}
case 'link-note-add':await changeCurrent(n=>n.links=[...new Set([...(n.links||[]),$('#link-note').value].filter(Boolean))]);await fullAction('links');return true;
case 'linked-open':closeDialog();await openNote(b.dataset.id);return true;
case 'gallery':{if(kind==='diary'){diaryGallery();return true}const items=activeNotes().flatMap(n=>{const d=new DOMParser().parseFromString(n.html,'text/html');return [...d.querySelectorAll('img,audio,video')].map(i=>({src:i.src,id:n.id,title:titleOf(n),kind:i.tagName.toLowerCase()}))});dialog('媒體畫廊',`<div class="gallery-grid">${items.map(i=>`<button data-action="linked-open" data-id="${esc(i.id)}">${i.kind==='img'?`<img src="${esc(i.src)}" alt="${esc(i.title)}">`:`<${i.kind} src="${esc(i.src)}" controls></${i.kind}>`}<small>${esc(i.title)}</small></button>`).join('')||'尚未有圖片'}</div>`);return true}
case 'review':{if(kind==='diary'){diaryReview();return true}const all=activeNotes(),year=new Date().getFullYear(),days={};all.forEach(n=>days[n.date]=(days[n.date]||0)+1);const anniversary=all.filter(n=>n.date?.slice(5)===today().slice(5)&&n.date!==today());let grid='';for(let i=0;i<366;i++){const d=new Date(year,0,1+i);if(d.getFullYear()!==year)break;const key=`${year}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;grid+=`<span title="${key}：${days[key]||0} 則" style="background:${days[key]?'#8b7cf8':'#edf0f7'}"></span>`}const moods={};all.forEach(n=>{if(n.mood)moods[n.mood]=(moods[n.mood]||0)+1});dialog('統計與回顧',`<div class="stats-grid"><b>${all.length}<small>篇記錄</small></b><b>${Object.keys(days).length}<small>記錄天數</small></b><b>${all.reduce((a,n)=>a+countWords(n),0)}<small>累計字數</small></b></div><h3>${year} 記錄熱力圖</h3><div class="heatmap">${grid}</div><h3>最近 7 天</h3><table><tr><th>日期</th><th>記錄</th><th>平均精力</th></tr>${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const ns=all.filter(n=>n.date===key),energy=ns.filter(n=>n.energy);return `<tr><td>${key}</td><td>${ns.length}</td><td>${energy.length?(energy.reduce((v,n)=>v+Number(n.energy),0)/energy.length).toFixed(1):'—'}</td></tr>`}).join('')}</table><h3>心情分佈</h3>${Object.entries(moods).map(([m,c])=>`<div>${esc(m)}　${c} 次 <meter value="${c}" max="${all.length}"></meter></div>`).join('')||'還沒有心情記錄'}<h3>那年今日</h3>${anniversary.map(n=>`<button class="secondary" data-action="linked-open" data-id="${esc(n.id)}">${esc(n.date+' '+titleOf(n))}</button>`).join('')||'沒有往年同一天的記錄'}`);return true}
case 'exports':dialog('分享與匯出',`<div class="hub-grid">${[['print','PDF／列印'],['word','Word 文件'],['long-image','分享長圖'],['export-note','Markdown'],['txt','純文字'],['html-export','網頁'],['zip','完整 ZIP 備份']].filter(([a])=>!(settings.hiddenFeatures||[]).includes(a)).map(([a,t])=>`<button class="secondary" data-action="${a}">${t}</button>`).join('')}</div>`);return true;
case 'print':closeDialog();window.print();return true;
case 'word':await exportWord();return true;
case 'long-image':closeDialog();await longImage();return true;
case 'txt':download(safeFilename(titleOf(getCurrent()))+'.txt',titleOf(getCurrent())+'\n\n'+textOf(rich.getHTML()),'text/plain');return true;
case 'html-export':download(safeFilename(titleOf(getCurrent()))+'.html','<!doctype html><meta charset="utf-8"><title>'+esc(titleOf(getCurrent()))+'</title><h1>'+esc(titleOf(getCurrent()))+'</h1>'+cleanHTML(rich.getHTML()),'text/html');return true;
case 'zip':await zipBackup();return true;
case 'encrypted':if(!crypto.subtle){toast('加密備份需要 HTTPS 或 localhost 安全環境');return true}dialog('加密備份',formField('密碼（最少 8 字元）','backup-pass','','password')+'<p>AES-GCM 加密。請自行保留密碼，無法重設或找回。</p><button class="primary" data-action="encrypted-confirm">下載加密備份</button>');return true;
case 'encrypted-confirm':await zipBackup(true);return true;
case 'decrypt-backup':try{const d=encryptedImport,key=await deriveKey($('#decrypt-pass').value,new Uint8Array(d.salt));const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(d.iv)},key,from64(d.data));closeDialog();await readBackup(new File([bytes],'backup.zip'))}catch{toast('密碼不正確或備份已損壞')}return true;
case 'media-file':{closePopover();const input=document.createElement('input');input.type='file';input.hidden=true;document.body.append(input);input.accept='audio/*,video/*';input.onchange=async()=>{const f=input.files[0];input.remove();if(!f)return;if(f.size>25*1024*1024){toast('音訊／影片上限 25 MB');return}const src=await readFile(f);rich.chain().focus().insertContent({type:'media',attrs:{src,kind:f.type.startsWith('video')?'video':'audio',name:f.name}}).run()};input.click();return true}
case 'record':if(!getCurrent()){toast('請先新增或開啟筆記');return true}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('目前瀏覽器不支援錄音，請用 HTTPS／localhost 開啟');return true}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onstop=async()=>{recordStream.getTracks().forEach(t=>t.stop());const blob=new Blob(recordChunks,{type:recorder.mimeType});const src=await readFile(blob);rich.chain().focus().insertContent({type:'media',attrs:{src,kind:'audio',name:'錄音 '+new Date().toLocaleString('zh-HK')}}).run()};recorder.start();dialog('錄音中','<p>完成後會插入目前筆記。</p><button class="secondary" data-action="record-pause">暫停／繼續</button><button class="primary" data-action="record-stop">完成錄音</button>')}catch{toast('未能使用麥克風，請檢查瀏覽器權限')}return true;
case 'record-pause':if(recorder?.state==='recording')recorder.pause();else if(recorder?.state==='paused')recorder.resume();return true;
case 'record-stop':if(recorder&&recorder.state!=='inactive')recorder.stop();closeDialog();return true;
case 'toolbar':dialog('自訂工具列',`<p>可隱藏少用工具，並調整順序。</p>${$$('.format-group button').map(el=>{const key=el.dataset.command||el.dataset.action;return `<div class="version-row"><label><input class="tool-show" type="checkbox" value="${key}" ${el.hidden?'':'checked'}>${esc(el.getAttribute('aria-label')||el.textContent)}</label><button data-action="tool-up" data-id="${key}">上移</button></div>`}).join('')}<button class="primary" data-action="toolbar-save">儲存</button>`);return true;
case 'tool-up':{const row=b.closest('.version-row'),prev=row.previousElementSibling;if(prev?.classList.contains('version-row'))prev.before(row);return true}
case 'toolbar-save':settings.hiddenTools=$$('.tool-show:not(:checked)').map(x=>x.value);settings.toolOrder=$$('.tool-show').map(x=>x.value);await storeConfig();applyToolbar();closeDialog();return true;
case 'feature-settings':dialog('功能顯示',`<p>關閉入口不會刪除記錄。</p>${[['gallery','媒體畫廊'],['review','統計回顧'],['templates','模板'],['books','筆記本']].map(([k,t])=>`<label class="full-field"><input class="feature-check" type="checkbox" value="${k}" ${!(settings.hiddenFeatures||[]).includes(k)?'checked':''}>${t}</label>`).join('')}<button class="primary" data-action="feature-save">儲存</button>`);return true;
case 'feature-save':settings.hiddenFeatures=$$('.feature-check:not(:checked)').map(x=>x.value);await storeConfig();closeDialog();return true;
default:return false}}

let diaryMonth='',diaryDay='',diaryMood='',diaryTag='';
function moodsOf(n){return Array.isArray(n.moods)?n.moods.filter(Boolean):n.mood?[n.mood]:[]}
function diaryRecords(){return activeNotes().filter(n=>n.kind==='diary'&&!n.archived)}
function localKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateLabel(key){const d=new Date(key+'T12:00:00');return isNaN(d)?key:d.toLocaleDateString('zh-HK',{...(d.getFullYear()!==new Date().getFullYear()?{year:'numeric'}:{}),month:'long',day:'numeric',weekday:'long'})}
function resultNotes(){let out=resultNotesBase();if(kind==='diary'&&filter!=='trash'){if(diaryMonth)out=out.filter(n=>n.date?.startsWith(diaryMonth));if(diaryDay)out=out.filter(n=>n.date===diaryDay);if(diaryMood)out=out.filter(n=>moodsOf(n).includes(diaryMood));if(diaryTag)out=out.filter(n=>(n.tags||[]).includes(diaryTag));if(sort!=='manual')out.sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.time||'').localeCompare(a.time||'')||b.created-a.created)}return out}
function coverOf(n){if(n.coverMode==='none')return null;if(n.cover?.src&&/^data:image\/(png|jpeg|webp|gif);base64,/i.test(n.cover.src))return n.cover;if(n.coverMode==='auto'){const doc=new DOMParser().parseFromString(n.html,'text/html'),img=doc.querySelector('img');return img?{src:img.src,alt:img.alt}:null}return null}
function renderList(){const isDiary=kind==='diary';$('#welcome h2').textContent=isDiary?'選擇一篇日記':'選擇一篇筆記';$('#welcome p').textContent=isDiary?'按日期翻看記錄，或寫下這一天。':'從清單開啟內容，或新增一篇筆記。';const label=$('.new-note>span');if(label)label.textContent='新增';$$('.mobile-create,.mobile-brand [data-action=new]').forEach(b=>b.setAttribute('aria-label','新增日記或筆記'));document.body.classList.toggle('diary-mode',isDiary);$('#diary-controls').hidden=!isDiary;if(!isDiary){renderNoteList();return}const pos=$('#note-list').scrollTop,out=resultNotes(),dates=[...new Set(out.map(n=>n.date))];$('#view-title').textContent=filter==='archive'?'已歸檔日記':filter==='trash'?'日記回收站':filter.startsWith('book:')?((settings.books||[]).find(b=>b.id===filter.slice(5))?.name||'日記本'):'我的日記';$('#diary-controls').innerHTML=`<div class="diary-monthbar"><button data-action="month-prev" aria-label="上一個月">‹</button><button class="month-name" data-action="date-index">${diaryDay?dateLabel(diaryDay):diaryMonth?diaryMonth.replace('-',' 年 ')+' 月':'所有日期'} ▾</button><button data-action="month-next" aria-label="下一個月">›</button></div><div class="diary-nav"><button data-action="diary-filter">篩選${diaryMood||diaryTag?' · 已選':''}</button><button data-action="books">筆記本</button><button data-action="diary-review">回顧</button><button data-action="diary-gallery">照片</button></div>${diaryDay||diaryMood||diaryTag||diaryMonth?'<button class="diary-clear" data-action="diary-clear">顯示全部日記</button>':''}`;$('#result-count').textContent=`${out.length} 篇 · ${dates.length} 天${sort==='manual'?' · 手動排序':' · 記錄日期排序'}`;$('#scope-toggle').hidden=true;let last='';$('#note-list').innerHTML=out.length?out.map(n=>{const day=n.date||today(),head=day!==last?`<div class="day-heading"><button data-action="day-open" data-id="${esc(day)}"><b>${esc(dateLabel(day))}</b><span>${out.filter(x=>x.date===day).length} 篇</span></button><button class="day-add" data-action="day-new" data-id="${esc(day)}" aria-label="在${esc(day)}新增日記">＋</button></div>`:'';last=day;const locked=n.unlock&&n.unlock>today(),cover=locked?null:coverOf(n);return head+`<button class="note-item diary-entry ${selected===n.id?'selected':''}" data-open="${esc(n.id)}">${cover?`<img class="entry-thumb" src="${esc(cover.src)}" alt="${esc(cover.alt||'日記封面')}" loading="lazy">`:''}<div class="entry-top"><h3>${highlighted(n.title?.trim()||'這一天的記錄')}</h3><time>${esc(n.time||'')}</time>${n.pinned?'<span class="entry-pin">✦</span>':''}</div><div class="entry-desc">${snippet(n)}</div><div class="diary-entry-meta">${moodsOf(n).map(m=>`<span>${esc(m)}</span>`).join('')}${n.energy?`<span>精力 ${Number(n.energy)}/5</span>`:''}${n.folder?`<span>${esc(n.folder)}</span>`:''}</div></button>`}).join(''):`<div class="empty-list"><h3>這裡還沒有日記</h3><p>換一個日期或篩選條件，或寫下這一天。</p><button class="primary" data-action="new">＋ 寫日記</button></div>`;$('#note-list').scrollTop=pos;renderNav();decorate()}
function renderDiaryWriter(n){const box=$('#diary-writer');if(!box)return;box.hidden=n.kind!=='diary';$('#title').placeholder=n.kind==='diary'?'為這一天加個標題（選填）':'標題（選填）';if(n.kind!=='diary')return;const mood=moodsOf(n),cover=coverOf(n);box.innerHTML=`<div class="diary-date-row"><label>記錄日期<input id="diary-date" type="date" value="${esc(n.date||today())}" aria-label="日記記錄日期"></label><label>時間<input id="diary-time" type="time" value="${esc(n.time||'')}" aria-label="日記記錄時間"></label><button data-action="diary-today">今天</button></div><div class="diary-feelings"><button class="mood-trigger" data-action="diary-moods">${mood.length?mood.map(esc).join(' · '):'＋ 心情（可複選）'}</button><button data-action="diary-energy">${n.energy?'精力 '+Number(n.energy)+'/5':'＋ 精力'}</button><button data-action="cover-picker">${cover?'更換封面':'＋ 封面'}</button></div>${cover?`<button class="writer-cover" data-action="cover-picker"><img src="${esc(cover.src)}" alt="日記封面"><span>封面 · 點擊更換</span></button>`:''}<div id="diary-suggestions" class="diary-suggestions" ${textOf(n.html)?'hidden':''}><span>如何開始？</span><button data-action="diary-free">自由記錄</button><button data-action="diary-template" data-id="每日記錄">每日記錄</button><button data-action="diary-template" data-id="晚間回顧">晚間回顧</button><button data-action="templates">更多模板</button></div><div class="diary-add-row"><button data-action="choose-image">＋ 照片</button><button data-action="record">錄音</button><button data-action="templates">模板</button><button data-action="full-meta">詳細資料</button></div><div class="record-timestamps">建立 ${esc(new Date(n.created).toLocaleString('zh-HK'))} · 修改 ${esc(new Date(n.updated).toLocaleString('zh-HK'))}</div>`}
function initDiaryUI(){document.addEventListener('input',e=>{const n=getCurrent();if(!n)return;if(e.target.id==='diary-date'){if(!/^\d{4}-\d\d-\d\d$/.test(e.target.value)){e.target.value=n.date;return}n.date=e.target.value;$('#record-date').value=n.date;queueSave();updateHeader()}if(e.target.id==='diary-time'){n.time=e.target.value;queueSave();updateHeader()}if(e.target.matches('.diary-mood-check')){n.moods=$$('.diary-mood-check:checked').map(x=>x.value);n.mood=n.moods[0]||'';queueSave()}if(e.target.id==='index-month'){showDateIndex(e.target.value)}});rich.on('update',()=>{const box=$('#diary-suggestions');if(box)box.hidden=!!textOf(rich.getHTML())});$('#dialog').addEventListener('close',()=>{if(getCurrent()?.kind==='diary')renderDiaryWriter(getCurrent())})}
function showDateIndex(month=diaryMonth||today().slice(0,7)){if(!/^\d{4}-\d\d$/.test(month))return;const y=Number(month.slice(0,4)),m=Number(month.slice(5)),length=new Date(y,m,0).getDate(),start=new Date(y,m-1,1).getDay();let days='';const all=diaryRecords();for(let i=0;i<start;i++)days+='<span></span>';for(let d=1;d<=length;d++){const key=month+'-'+String(d).padStart(2,'0'),rows=all.filter(n=>n.date===key);days+=`<button class="date-cell ${key===today()?'is-today':''}" data-action="index-day" data-id="${key}"><b>${d}</b><small>${rows.length?rows.length+' 篇':''}</small></button>`}dialog('日記日期索引',`<input id="index-month" type="month" value="${month}" aria-label="選擇日記月份"><div class="date-index"><span>日</span><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span>${days}</div><div class="dialog-footer"><button class="secondary" data-action="index-month-open" data-id="${month}">查看整月</button><button class="primary" data-action="diary-clear">所有日記</button></div>`)}
async function diaryGallery(){await flush();const rows=diaryRecords().filter(n=>!n.unlock||n.unlock<=today()).flatMap(n=>{const doc=new DOMParser().parseFromString(n.html,'text/html');let images=[...doc.querySelectorAll('img')].map(i=>({src:i.src,alt:i.alt}));const cover=coverOf(n);if(cover&&!images.some(i=>i.src===cover.src))images.unshift(cover);return images.map(image=>({n,image}))});dialog('日記照片',`<p>只顯示日記中的照片與獨立封面。</p><div class="gallery-grid">${rows.map(({n,image})=>`<button data-action="linked-open" data-id="${esc(n.id)}"><img src="${esc(image.src)}" alt="${esc(image.alt||'照片')}"><small>${esc(n.date)} · ${esc(n.title||'日記')}</small></button>`).join('')||'尚未加入照片'}</div>`)}
async function diaryReview(){await flush();const all=diaryRecords(),days=[...new Set(all.map(n=>n.date))],moods={};all.forEach(n=>moodsOf(n).forEach(m=>moods[m]=(moods[m]||0)+1));const months=[...new Set(all.map(n=>n.date?.slice(0,7)).filter(Boolean))].sort().reverse(),past=all.filter(n=>n.date?.slice(5)===today().slice(5)&&n.date<today());const recent=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-i);const key=localKey(d),ns=all.filter(n=>n.date===key),energy=ns.filter(n=>n.energy),ms=[...new Set(ns.flatMap(moodsOf))];return `<button class="review-day" data-action="review-day" data-id="${key}"><b>${key}</b><span>${ns.length} 篇 · ${ms.map(esc).join('、')||'未記心情'}${energy.length?' · 精力 '+(energy.reduce((a,n)=>a+Number(n.energy),0)/energy.length).toFixed(1):''}</span></button>`}).join('');dialog('日記回顧',`<p>統計範圍：全部未歸檔日記。心情可複選，次數可能多於篇數。</p><div class="stats-grid"><button data-action="review-all"><b>${all.length}</b><small>篇日記</small></button><button data-action="date-index"><b>${days.length}</b><small>記錄天數</small></button><button data-action="diary-gallery"><b>照片</b><small>翻看日記</small></button></div><h3>最近 7 天</h3>${recent}<h3>心情記錄</h3><div class="mood-review">${Object.entries(moods).map(([m,c])=>`<button data-action="review-mood" data-id="${esc(m)}">${esc(m)} <b>${c}</b></button>`).join('')||'尚未記錄心情'}</div><h3>按月回看</h3><div class="month-review">${months.map(m=>`<button class="secondary" data-action="review-month" data-id="${m}">${m} · ${all.filter(n=>n.date?.startsWith(m)).length} 篇</button>`).join('')}</div><h3>那年今日</h3>${past.map(n=>`<button class="review-day" data-action="linked-open" data-id="${esc(n.id)}">${esc(n.date+' · '+(n.title||'日記'))}</button>`).join('')||'沒有往年同一天的日記'}`)}
function showCoverPicker(){const n=getCurrent();if(!n)return;const doc=new DOMParser().parseFromString(rich.getHTML(),'text/html'),images=[...doc.querySelectorAll('img')];dialog('選擇日記封面',`<p>封面獨立於正文；更換或移除封面不會刪除正文圖片。</p><div class="cover-options">${images.map((img,i)=>`<button data-action="cover-image" data-index="${i}"><img src="${esc(img.src)}" alt="${esc(img.alt||'圖片')}"></button>`).join('')||'<p>正文暫時沒有圖片，可另外上傳一張。</p>'}</div><div class="dialog-footer"><button class="secondary" data-action="cover-none">不顯示封面</button><button class="primary" data-action="cover-upload">另外上傳封面</button></div>`)}
async function showDiaryResult(set){if(!(await flush()))return;kind='diary';settings.lastKind='diary';filter='all';query='';scopeAll=false;$('#search').value='';diaryMonth='';diaryDay='';diaryMood='';diaryTag='';set?.();selected=null;$('#welcome').hidden=false;$('#document-view').hidden=true;document.body.classList.remove('editor-open','focus-mode');closeDialog();renderList();await storeConfig()}
async function diaryAction(a,b){switch(a){
case 'diary-clear':await showDiaryResult();return true;
case 'diary-review':await diaryReview();return true;
case 'diary-gallery':await diaryGallery();return true;
case 'date-index':showDateIndex();return true;
case 'month-prev':case 'month-next':{const base=diaryMonth||today().slice(0,7),d=new Date(Number(base.slice(0,4)),Number(base.slice(5))-1+(a==='month-next'?1:-1),1);diaryMonth=localKey(d).slice(0,7);diaryDay='';renderList();return true}
case 'index-month-open':case 'review-month':await showDiaryResult(()=>diaryMonth=b.dataset.id);return true;
case 'index-day':case 'day-open':case 'review-day':await showDiaryResult(()=>{diaryDay=b.dataset.id;diaryMonth=diaryDay.slice(0,7)});return true;
case 'review-mood':await showDiaryResult(()=>diaryMood=b.dataset.id);return true;
case 'review-all':await showDiaryResult();return true;
case 'day-new':diaryDay=b.dataset.id;await createNote();return true;
case 'diary-today':{const n=getCurrent();n.date=today();$('#record-date').value=n.date;queueSave();updateHeader();return true}
case 'diary-moods':{const n=getCurrent(),selectedMoods=moodsOf(n),choices=[...new Set([...(settings.moods||['😊 開心','😌 平靜','😔 低落','😴 疲倦','🥰 感恩','😟 擔心']),...selectedMoods])];dialog('此刻的心情',`<p>可以同時選擇多個，也可以留空。</p><div class="mood-choices">${choices.map(m=>`<label><input class="diary-mood-check" type="checkbox" value="${esc(m)}" ${selectedMoods.includes(m)?'checked':''}>${esc(m)}</label>`).join('')}</div><div class="dialog-footer"><button class="secondary" data-action="moods">編輯選項</button><button class="primary" data-action="moods-done">完成</button></div>`);return true}
case 'moods-done':closeDialog();updateHeader();await flush();return true;
case 'diary-energy':dialog('現在的精力',`<p>選填，1 為非常疲倦，5 為精神充沛。</p><div class="energy-choices">${[1,2,3,4,5].map(v=>`<button data-action="energy-set" data-id="${v}" class="${Number(getCurrent().energy)===v?'selected':''}">${v}</button>`).join('')}</div><button class="secondary" data-action="energy-set" data-id="">略過／清除</button>`);return true;
case 'energy-set':getCurrent().energy=b.dataset.id?Number(b.dataset.id):'';queueSave();closeDialog();updateHeader();return true;
case 'diary-free':editor.focus();return true;
case 'diary-template':{const t=builtinTemplates.find(t=>t.name===b.dataset.id);if(t)insertHTML(t.html.replaceAll('{{日期}}',getCurrent().date));return true}
case 'diary-filter':{const all=diaryRecords(),m=[...new Set(all.flatMap(moodsOf))],tags=[...new Set(all.flatMap(n=>n.tags||[]))];dialog('篩選日記',`<label class="full-field">心情<select id="diary-filter-mood"><option value="">所有心情</option>${m.map(x=>`<option ${x===diaryMood?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="full-field">標籤<select id="diary-filter-tag"><option value="">所有標籤</option>${tags.map(x=>`<option ${x===diaryTag?'selected':''}>${esc(x)}</option>`).join('')}</select></label><button class="primary" data-action="diary-filter-apply">套用篩選</button>`);return true}
case 'diary-filter-apply':diaryMood=$('#diary-filter-mood').value;diaryTag=$('#diary-filter-tag').value;closeDialog();renderList();return true;
case 'cover-picker':showCoverPicker();return true;
case 'cover-image':{const imgs=[...editor.querySelectorAll('img')],img=imgs[Number(b.dataset.index)];if(img){const n=getCurrent();n.cover={src:img.src,alt:img.alt};n.coverMode='custom';queueSave();closeDialog();updateHeader()}return true}
case 'cover-none':getCurrent().cover=null;getCurrent().coverMode='none';queueSave();closeDialog();updateHeader();return true;
case 'cover-upload':{const n=getCurrent(),input=document.createElement('input');input.type='file';input.hidden=true;document.body.append(input);input.accept='image/png,image/jpeg,image/webp,image/gif';input.onchange=async()=>{const f=input.files[0];input.remove();if(!f)return;if(f.size>10*1024*1024){toast('封面上限為 10 MB');return}if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type)){toast('請選擇 PNG、JPEG、WebP 或 GIF');return}const src=await readFile(f);n.cover={src,alt:f.name};n.coverMode='custom';n.updated=Date.now();await storeNote(n);if(selected===n.id){closeDialog();updateHeader()}renderList()};input.click();return true}
default:return false}}

// Calendar notes mobile flow. Quick capture is stored as a note with capture='quick'.
function isQuick(n){return n.kind==='note'&&n.capture==='quick'}
function matchesKind(n){return kind==='all'||(kind==='quick'?isQuick(n):n.kind===kind&&!isQuick(n))}
function recordName(n){return n.kind==='diary'?'日記':isQuick(n)?'隨手記':'筆記'}
function setReading(value){document.body.classList.toggle('reading',value);rich.setEditable(!value,false);$('#title').readOnly=value;$$('[data-action=edit-current]').forEach(b=>b.hidden=!value);$('.doc-actions .done').hidden=value;if(getCurrent())renderContext(getCurrent());}
function renderRecordControls(){
 $$('.record-chips button').forEach(b=>{const active=b.dataset.kind===kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 $('#note-list').classList.toggle('record-grid',settings.recordLayout==='grid');document.body.classList.toggle('comfortable-list',settings.recordDensity==='comfortable');
 $$('#note-list .note-item').forEach(el=>{const n=notes.find(x=>x.id===el.dataset.open);if(!n)return;el.classList.toggle('capture-quick',isQuick(n));if(!el.querySelector('.entry-eyebrow'))el.insertAdjacentHTML('afterbegin',`<div class="entry-eyebrow"><span>${esc(n.kind==='diary'?(n.date||''):prettyDate(n.updated))}${n.pinned?' · 置頂':''}</span><span>${esc(moodsOf(n)[0]||'')}</span></div>`);const bottom=el.querySelector('.entry-bottom')||el.querySelector('.diary-entry-meta');if(bottom&&!bottom.querySelector('.entry-kind'))bottom.insertAdjacentHTML('afterbegin',`<span class="entry-kind">${recordName(n)}</span>`);});
 const more=$('[data-action=record-layout]');if(more)more.setAttribute('aria-pressed',String(settings.recordLayout==='grid'));
}
function renderContext(n){
 const c=n.weatherSnapshot,values=[recordName(n),n.folder||'未分類',...(n.kind==='diary'?moodsOf(n):[])];
 $('#read-detail').innerHTML=values.map(v=>`<span>${esc(v)}</span>`).join('');$('#read-detail').hidden=!document.body.classList.contains('reading');
 const brief=$('#context-brief');brief.hidden=!c;brief.textContent=c?[c.location,c.description,c.temperature!==null&&c.temperature!==''&&c.temperature!==undefined?c.temperature+'°C':'',c.source==='skysignal'?'晴訊 · Open-Meteo 模式估算':'手動輸入',c.observedAt?'資料時間 '+new Date(c.observedAt).toLocaleString('zh-HK'):''].filter(Boolean).join(' · '):'';
 $('#breadcrumb').textContent=recordName(n)+' / '+(n.folder||'未分類');
}
async function showCreateChooser(){if(!await flush())return;dialog('新增內容',`<div class="create-choices"><button data-action="create-diary">${icon('book')}<span><strong>寫日記</strong><small>記錄生活、心情與值得留下的片刻</small></span></button><button data-action="create-note">${icon('note')}<span><strong>寫筆記</strong><small>整理知識、想法與完整內容</small></span></button></div>`)}
