let weatherController=null,weatherDraft=null,weatherNoteId=null,weatherSession=0;
function cancelWeather(){weatherSession++;weatherController?.abort();weatherController=null;weatherDraft=null;weatherNoteId=null;}
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open)cancelWeather()});
function contextMenu(){cancelWeather();const n=getCurrent();if(!n)return;dialog('天氣與地點',`<div class="create-choices"><button data-action="context-manual">${icon('edit')}<span><strong>手動輸入</strong><small>填寫天氣、溫度與地點，不使用定位</small></span></button><button data-action="context-auto">${icon('weather')}<span><strong>使用晴訊</strong><small>同意定位後取得當地天氣，確認才加入</small></span></button></div>${n.weatherSnapshot?'<div class="dialog-footer"><button class="secondary" data-action="context-remove">移除這篇的天氣與地點</button></div>':''}`)}
function manualContext(){cancelWeather();const c=getCurrent()?.weatherSnapshot||{};dialog('手動輸入',formField('地點','context-location',c.location||'')+formField('天氣','context-description',c.description||'')+formField('溫度（°C，選填）','context-temperature',c.temperature??'','number')+'<div class="dialog-footer"><button class="secondary" data-action="note-context">返回</button><button class="primary" data-action="context-save">加入這篇記錄</button></div>');$('#context-temperature').step='0.1';$('#context-temperature').min='-90';$('#context-temperature').max='65';}
async function requestWeather(){
 cancelWeather();const id=selected,session=weatherSession;weatherNoteId=id;weatherController=new AbortController();
 dialog('晴訊 · 定位與天氣','<p class="context-warning">只在這次查詢使用定位，座標會傳給 Open-Meteo 取得當地模式估算。資料先預覽，確認後才加入記錄。</p><p id="weather-status" role="status" aria-live="polite">正在要求定位並查詢天氣…</p><div class="dialog-footer"><button class="secondary" data-action="context-manual">改用手動輸入</button><button class="secondary" data-action="close-dialog">取消</button></div>');
 try{
  const result=await SkySignalNotes.locateAndFetch({signal:weatherController.signal});
  if(session!==weatherSession||selected!==id||!$('#dialog').open)return;
  weatherDraft=result;
  $('#dialog-body').innerHTML=`<div class="weather-preview"><span>晴訊 · Open-Meteo 模式估算</span><strong>${esc(result.description)} · ${esc(result.temperature)}°C</strong><label>地點名稱（可修改）<input id="weather-location" maxlength="200" value="${esc(result.location)}"></label><small>資料時間：${esc(new Date(result.observedAt).toLocaleString('zh-HK'))}${result.accuracy?' · 定位精度約 '+result.accuracy+' 米':''}</small></div><p class="context-warning">這是目前天氣估算，並非歷史實測；加入後保存這一刻的資料，不會隨天氣改變。</p><p class="context-warning">記錄日期：${esc(getCurrent()?.date||today())}。請確認適用於這篇記錄。</p><p><a href="https://open-meteo.com/" target="_blank" rel="noopener">Weather data by Open-Meteo</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a></p><div class="dialog-footer"><button class="secondary" data-action="context-manual">手動輸入</button><button class="primary" data-action="context-apply">確認加入</button></div>`;
 }catch(e){if(session!==weatherSession||selected!==id||!$('#dialog').open)return;$('#weather-status').className='context-error';$('#weather-status').textContent=e.message||'無法取得天氣，請改用手動輸入。';}
}
async function unifiedAction(a,b){switch(a){
 case 'new':await showCreateChooser();return true;
 case 'create-diary':case 'create-note':closeDialog();await navigate(a==='create-diary'?'diary':'note','all');await createNote();return true;
 case 'finish-edit':if(await flush()){setReading(true);document.activeElement?.blur();toast('已儲存')}return true;
 case 'edit-current':setReading(false);editor.focus();return true;
 case 'meta':if(document.body.classList.contains('reading')){setReading(false);metaOpen=true;updateHeader();return true}return false;
 case 'reader':if(await flush()){setReading(!document.body.classList.contains('reading'));closePopover()}return true;
 case 'quick-capture':if(!await flush())return true;dialog('隨手記','<div class="quick-paper"><label for="quick-text">先留下想法，之後再整理。</label><textarea id="quick-text" placeholder="想到甚麼，就寫下來…" aria-label="隨手記內容"></textarea></div><button class="primary wide-action" data-action="quick-save">收進筆記</button>');$('#quick-text').focus();return true;
 case 'quick-save':{const text=$('#quick-text').value.trim();if(!text){toast('先寫一點內容吧');return true}const now=Date.now(),n={id:uid(),kind:'note',capture:'quick',title:text.split('\n')[0].slice(0,70),html:'<p>'+esc(text).replaceAll('\n','<br>')+'</p>',folder:'',tags:[],date:today(),created:now,updated:now,deleted:false,history:[]};await storeNote(n);notes.push(n);closeDialog();await navigate('all','all');toast('已收進隨手記');return true}
 case 'records-home':await navigate('all','all');return true;
 case 'record-books':if(await flush())showRecordBooks();return true;
 case 'folder-browse':closeDialog();await navigate('all',b.dataset.folder?'folder:'+b.dataset.folder:'inbox');return true;
 case 'record-layout':settings.recordLayout=settings.recordLayout==='grid'?'list':'grid';await storeConfig();renderList();return true;
 case 'record-density':settings.recordDensity=settings.recordDensity==='comfortable'?'compact':'comfortable';await storeConfig();renderRecordControls();return true;
 case 'hub':hub();$('#dialog-body').insertAdjacentHTML('afterbegin','<div class="display-choices"><button data-action="record-layout">切換清單／卡片</button><button data-action="record-density">切換記錄密度</button><button data-action="archive-view">已歸檔</button><button data-action="trash-view">回收站</button></div>');return true;
 case 'trash-view':closeDialog();await navigate('all','trash');return true;
 case 'note-context':if(await flush())contextMenu();return true;
 case 'context-manual':manualContext();return true;
 case 'context-auto':await requestWeather();return true;
 case 'context-save':{const temperature=$('#context-temperature');if(!temperature.checkValidity()){temperature.reportValidity();return true}const value={source:'manual',location:$('#context-location').value.trim().slice(0,200),description:$('#context-description').value.trim().slice(0,100),temperature:temperature.value===''?null:Number(temperature.value),retrievedAt:new Date().toISOString()};await changeCurrent(n=>n.weatherSnapshot=value.location||value.description||value.temperature!==null?value:null);closeDialog();toast('已儲存天氣與地點');return true}
 case 'context-apply':{if(!weatherDraft||selected!==weatherNoteId){toast('記錄已切換，請重新取得天氣');return true}const value={...weatherDraft,location:$('#weather-location').value.trim().slice(0,200)||weatherDraft.location};await changeCurrent(n=>n.weatherSnapshot=value);closeDialog();toast('已加入這一刻的天氣與地點');return true}
 case 'context-remove':await changeCurrent(n=>n.weatherSnapshot=null);closeDialog();return true;
 default:return false;
}}
